15:func ensureDiscoveryRepository(ctx context.Context, options repostate.Options) (repostate.Status, error) {
16:	grimoireCommand := filepath.Clean(strings.TrimSpace(options.GrimoireCommand))
17:	options.Run = func(commandContext context.Context, command repostate.ProcessCommand) error {
18:		arguments := command.Arguments
19:		if sameDiscoveryCommand(command.Executable, grimoireCommand) && len(arguments) > 0 {
20:			switch arguments[0] {
21:			case "index":
22:				return runIndex(arguments[1:], io.Discard, io.Discard)
23:			case "knowledge":
24:				if len(arguments) > 1 && arguments[1] == "index" {
25:					return runKnowledge(arguments[1:], io.Discard, io.Discard)
26:				}
27:			}
28:		}
29:		return runDiscoveryCommand(commandContext, command)
30:	}
31:	return repostate.Ensure(ctx, options)
32:}
33:
34:func sameDiscoveryCommand(command, expected string) bool {
35:	command = filepath.Clean(strings.TrimSpace(command))
36:	if command == "" || expected == "" {
37:		return false
38:	}
39:	return strings.EqualFold(command, expected)
40:}
41:
42:func runDiscoveryCommand(ctx context.Context, command repostate.ProcessCommand) error {
43:	var stdout, stderr bytes.Buffer
44:	process := exec.CommandContext(ctx, command.Executable, command.Arguments...)
45:	if len(command.Environment) > 0 {
46:		process.Env = command.Environment
47:	}
48:	process.Stdout = &stdout
49:	process.Stderr = &stderr
50:	if err := process.Run(); err != nil {
51:		message := strings.TrimSpace(stderr.String())
52:		if message == "" {
53:			message = strings.TrimSpace(stdout.String())
54:		}
55:		if message != "" {
56:			return fmt.Errorf("%w: %s", err, message)
57:		}
58:		return err
59:	}
60:	return nil
61:}

