191:func perform(ctx context.Context, status *Status, name string, runner CommandRunner, command ProcessCommand) error {
192:	started := now()
193:	action := Action{Name: name, Status: "running"}
194:	status.Actions = append(status.Actions, action)
195:	if runner == nil {
196:		runner = runCommand
197:	}
198:	err := runner(ctx, command)
199:	last := &status.Actions[len(status.Actions)-1]
200:	last.ElapsedMS = elapsedMS(started)
201:	status.Timings.addAction(name, last.ElapsedMS)
202:	if err != nil {
203:		last.Status = "failed"
204:		last.Error = err.Error()
205:		return fmt.Errorf("%s: %w", name, err)
206:	}
207:	last.Status = "completed"
208:	return nil
209:}
