24:func Run(ctx context.Context, scanner *scan.Scanner, options Options) error {
25:	watcher, err := fsnotify.NewWatcher()
26:	if err != nil {
27:		return err
28:	}
29:	defer watcher.Close()
30:	policy, err := lexfiles.LoadIgnorePolicy(scanner.Repository)
31:	if err != nil {
32:		return err
33:	}
34:	if err := addTree(watcher, scanner.Repository, policy); err != nil {
35:		return err
36:	}
37:	if report, err := scanner.Scan(ctx); err != nil {
38:		return err
39:	} else {
40:		writeReport(options.Output, "startup", report)
41:	}
42:	if options.Debounce <= 0 {
43:		options.Debounce = 150 * time.Millisecond
44:	}
45:	if options.Reconcile <= 0 {
46:		options.Reconcile = 30 * time.Second
47:	}
48:	pending := make(map[string]struct{})
49:	fullScan := false
50:	var timer *time.Timer
51:	var timerChannel <-chan time.Time
52:	reconcile := time.NewTicker(options.Reconcile)
53:	defer reconcile.Stop()
54:	for {
55:		select {
56:		case <-ctx.Done():
57:			return nil
58:		case event, ok := <-watcher.Events:
59:			if !ok {
60:				return nil
61:			}
62:			if lexfiles.IsIgnoreFile(scanner.Repository, event.Name) {
63:				policy, err = lexfiles.LoadIgnorePolicy(scanner.Repository)
64:				if err != nil {
65:					return err
66:				}
67:				if err := addTree(watcher, scanner.Repository, policy); err != nil {
68:					return err
69:				}
70:				clear(pending)
71:				fullScan = true
72:				if timer == nil {
73:					timer = time.NewTimer(options.Debounce)
74:				} else if !timer.Stop() {
75:					select {
76:					case <-timer.C:
77:					default:
78:					}
79:				}
80:				timer.Reset(options.Debounce)
81:				timerChannel = timer.C
82:				continue
83:			}
84:			if ignored(policy, event.Name) {
85:				continue
86:			}
87:			if event.Op&fsnotify.Create != 0 {
88:				if info, statErr := os.Stat(event.Name); statErr == nil && info.IsDir() {
89:					_ = addTree(watcher, event.Name, policy)
90:				}
91:			}
92:			if relevantEvent(event) {
93:				pending[event.Name] = struct{}{}
94:				if timer == nil {
95:					timer = time.NewTimer(options.Debounce)
96:				} else if !timer.Stop() {
97:					select {
98:					case <-timer.C:
99:					default:
100:					}
101:				}
102:				timer.Reset(options.Debounce)
103:				timerChannel = timer.C
104:			}
105:		case <-timerChannel:
106:			paths := sortedKeys(pending)
107:			clear(pending)
108:			timerChannel = nil
109:			var report scan.Report
110:			var scanErr error
111:			if fullScan {
112:				fullScan = false
113:				report, scanErr = scanner.Scan(ctx)
114:			} else {
115:				report, scanErr = scanner.ScanPaths(ctx, paths)
116:			}
117:			if scanErr != nil {
118:				fmt.Fprintf(options.Output, "lexicon demon scan failed: %v\n", scanErr)
119:				continue
120:			}
121:			writeReport(options.Output, "watch", report)
122:		case watchErr, ok := <-watcher.Errors:
123:			if !ok {
124:				return nil
125:			}
126:			fmt.Fprintf(options.Output, "lexicon watcher error: %v; reconciling\n", watchErr)
127:			report, scanErr := scanner.Scan(ctx)
128:			if scanErr != nil {
