144:func addTree(watcher *fsnotify.Watcher, root string, policy lexfiles.IgnorePolicy) error {
145:	return filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
146:		if walkErr != nil {
147:			return walkErr
148:		}
149:		if !entry.IsDir() {
150:			return nil
151:		}
152:		if path != root && policy.Ignored(path, true) {
153:			return filepath.SkipDir
154:		}
155:		return watcher.Add(path)
156:	})
157:}
158:
159:func ignored(policy lexfiles.IgnorePolicy, path string) bool {
160:	info, err := os.Lstat(path)
161:	return policy.Ignored(path, err == nil && info.IsDir())
162:}
163:
164:func relevantEvent(event fsnotify.Event) bool {
165:	if event.Op&(fsnotify.Remove|fsnotify.Rename) != 0 {
166:		return true
167:	}
168:	if lexfiles.Relevant(event.Name) {
169:		return true
170:	}
171:	info, err := os.Stat(event.Name)
172:	return err == nil && info.IsDir()
173:}
174:
175:func sortedKeys(values map[string]struct{}) []string {
176:	result := make([]string, 0, len(values))
177:	for value := range values {
178:		result = append(result, value)
179:	}
180:	sort.Strings(result)
181:	return result
182:}
183:
184:func writeReport(output io.Writer, source string, report scan.Report) {
185:	if output == nil || len(report.Changed) == 0 {
186:		return
187:	}
188:	fmt.Fprintf(output, "%s scan: %d files, %s\n", source, len(report.Changed), strings.Join(report.Languages, ", "))
189:}

