18:
19:func Run(arguments []string, stdout, stderr io.Writer) int {
20:	if len(arguments) == 0 {
21:		usage(stderr)
22:		return 2
23:	}
24:	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
25:	defer stop()
26:	var err error
27:	switch arguments[0] {
28:	case "init":
29:		err = runInit(ctx, arguments[1:], stdout, stderr)
30:	case "scan":
31:		err = runScan(ctx, arguments[1:], stdout, stderr)
32:	case "demon":
33:		err = runDemon(ctx, arguments[1:], stdout, stderr)
34:	case "rebuild":
35:		err = runRebuild(ctx, arguments[1:], stdout, stderr)
36:	case "export":
37:		err = runExport(arguments[1:], stdout, stderr)
38:	case "gc":
39:		err = runGC(arguments[1:], stdout, stderr)
40:	case "languages":
41:		err = runLanguages(ctx, arguments[1:], stdout, stderr)
42:	case "consumer":
43:		err = runConsumer(ctx, arguments[1:], stdout, stderr)
44:	case "status":
45:		err = runStatus(arguments[1:], stdout, stderr)
46:	case "doctor":
47:		err = runDoctor(arguments[1:], stdout, stderr)
48:	case "version":
49:		err = runVersion(stdout)
50:	case "help", "-h", "--help":
51:		usage(stdout)
52:		return 0
53:	default:
54:		fmt.Fprintf(stderr, "unknown command %q\n", arguments[0])
55:		usage(stderr)
56:		return 2
57:	}
58:	if err != nil {
59:		fmt.Fprintln(stderr, err)
60:		return 1
61:	}
62:	return 0
63:}
64:
65:func runInit(ctx context.Context, arguments []string, stdout, stderr io.Writer) error {
66:	flags := flag.NewFlagSet("init", flag.ContinueOnError)
67:	flags.SetOutput(stderr)
68:	repository := flags.String("repo", "", "repository to initialize")
69:	adapterRoot := flags.String("adapters", "", "Lexicon adapters directory")
70:	languageText := flags.String("languages", "", "comma-separated languages or all")
71:	if err := flags.Parse(arguments); err != nil {
72:		return err
73:	}
74:	root, err := initRepository(*repository)
75:	if err != nil {
76:		return err
77:	}
78:	adapters, err := config.FindAdapterRoot(root, *adapterRoot)
79:	if err != nil {
80:		return err
81:	}
82:	var report scan.Report
83:	if flagWasSet(flags, "languages") {
84:		selection, err := parseLanguageSelection(*languageText)
85:		if err != nil {
86:			return err
87:		}
88:		_, report, err = scan.InitializeWithLanguages(ctx, root, adapters, selection, stdout)
89:	} else {
90:		_, report, err = scan.Initialize(ctx, root, adapters, stdout)
91:	}
92:	if err != nil {
93:		return err
94:	}
95:	fmt.Fprintf(stdout, "initialized Lexicon: %s\n", root)
96:	if len(report.Languages) > 0 {
97:		fmt.Fprintf(stdout, "libraries: %s\n", strings.Join(report.Languages, ", "))
98:	}
99:	fmt.Fprintf(stdout, "snapshot: %s\n", report.SnapshotID)
100:	return nil
101:}
102:
103:func runScan(ctx context.Context, arguments []string, stdout, stderr io.Writer) error {
104:	flags := flag.NewFlagSet("scan", flag.ContinueOnError)
105:	flags.SetOutput(stderr)
106:	repository := flags.String("repo", "", "repository to scan")
107:	if err := flags.Parse(arguments); err != nil {
108:		return err
109:	}
110:	root, err := resolveRepository(*repository)
111:	if err != nil {
112:		return err
113:	}
114:	scanner, err := scan.Open(root, stdout)
115:	if err != nil {
116:		return err
117:	}
118:	report, err := scanner.Scan(ctx)
119:	if err != nil {
120:		return err
121:	}
122:	if len(report.Changed) == 0 {
123:		if len(report.Languages) > 0 {
124:			fmt.Fprintf(stdout, "rebuilt libraries: %s\n", strings.Join(report.Languages, ", "))
125:			fmt.Fprintf(stdout, "snapshot: %s\n", report.SnapshotID)
126:			return nil
127:		}
128:		fmt.Fprintf(stdout, "Lexicon is current: %s\n", report.SnapshotID)
129:		return nil
130:	}
131:	fmt.Fprintf(stdout, "updated %d files: %s\n", len(report.Changed), strings.Join(report.Languages, ", "))
132:	fmt.Fprintf(stdout, "snapshot: %s\n", report.SnapshotID)
133:	return nil
134:}
135:
136:func runDemon(ctx context.Context, arguments []string, stdout, stderr io.Writer) error {
137:	flags := flag.NewFlagSet("demon", flag.ContinueOnError)
138:	flags.SetOutput(stderr)
139:	repository := flags.String("repo", "", "repository to watch")
140:	debounce := flags.Duration("debounce", 150*time.Millisecond, "quiet period before scanning changes")
141:	reconcile := flags.Duration("reconcile", 30*time.Second, "full reconciliation interval")
142:	if err := flags.Parse(arguments); err != nil {
143:		return err
144:	}
145:	root, err := resolveRepository(*repository)
146:	if err != nil {
147:		return err
148:	}
149:	scanner, err := scan.Open(root, stdout)
150:	if err != nil {
151:		return err
152:	}
153:	fmt.Fprintf(stdout, "Lexicon demon watching %s\n", scanner.Repository)
154:	return lexwatch.Run(ctx, scanner, lexwatch.Options{Debounce: *debounce, Reconcile: *reconcile, Output: stderr})
155:}
156:
157:func usage(output io.Writer) {
158:	fmt.Fprintln(output, "Usage: lexicon <init|scan|demon|rebuild|export|gc|languages|consumer|status|doctor|version> [options]")
159:}

