155:
156:	sourceSpans, lexiconSnapshot, spanErr := resolveIndexSourceSpans(
157:		*root, statePath, *lexiconFacts, *lexiconState, *lexiconCommand,
158:	)
159:	if spanErr != nil {
160:		if strings.TrimSpace(*lexiconFacts) != "" || strings.TrimSpace(*lexiconState) != "" {
161:			return fmt.Errorf("resolve Lexicon semantic spans: %w", spanErr)
162:		}
163:		_, _ = fmt.Fprintf(stderr, "warning: Lexicon semantic spans unavailable; using line-window chunking: %v\n", spanErr)
164:	}
165:
166:	excluded := append([]string{statePath}, excludePaths...)
167:	snapshot, stats, err := index.Build(*root, previous, index.BuildOptions{
168:		MaxFileBytes:     *maxFileBytes,
169:		IgnoreFile:       *ignoreFile,
170:		ExcludePaths:     excluded,
171:		IncludeGenerated: *includeGenerated,
172:		SourceSpans:      sourceSpans,
173:	})
174:	if err != nil {
175:		return err
176:	}
177:	if err := index.Save(statePath, snapshot); err != nil {
178:		return err
179:	}
