198:func resolveState(root, state string) (string, error) {
199:	absoluteRoot, err := filepath.Abs(root)
200:	if err != nil {
201:		return "", fmt.Errorf("resolve root: %w", err)
202:	}
203:	if state == "" {
204:		state = strings.TrimSpace(os.Getenv("GRIMOIRE_STATE_DIR"))
205:		if state == "" {
206:			return filepath.Join(absoluteRoot, ".grimoire"), nil
207:		}
208:	}
209:	if filepath.IsAbs(state) {
210:		return filepath.Clean(state), nil
211:	}
212:	return filepath.Join(absoluteRoot, state), nil
213:}
