215:func loadOptional(path string) (*index.Snapshot, error) {
216:	snapshot, err := index.Load(path)
217:	if errors.Is(err, os.ErrNotExist) {
218:		return nil, nil
219:	}
220:	if errors.Is(err, index.ErrIncompatibleIndex) {
221:		base, rebuildErr := index.RebuildBase(path)
222:		if rebuildErr != nil {
223:			return nil, fmt.Errorf("prepare index rebuild: %w", rebuildErr)
224:		}
225:		return &base, nil
226:	}
227:	if err != nil {
228:		return nil, fmt.Errorf("load existing index: %w", err)
229:	}
230:	return &snapshot, nil
231:}
